import { Field, FieldItem, FieldLabel } from "@/registry/erbium/ui/field";
import { RadioGroup, RadioGroupItem } from "@/registry/erbium/ui/radio-group";

const RadioGroupReadOnly = () => (
  <Field>
    <RadioGroup readOnly defaultValue="pro">
      <FieldItem orientation="horizontal">
        <RadioGroupItem value="free" />
        <FieldLabel>Free</FieldLabel>
      </FieldItem>
      <FieldItem orientation="horizontal">
        <RadioGroupItem value="pro" />
        <FieldLabel>Pro (current plan)</FieldLabel>
      </FieldItem>
    </RadioGroup>
  </Field>
);

export default RadioGroupReadOnly;

import ExampleRadioGroupReadOnly from "../examples/radio-group-read-only";

const Example = () => <ExampleRadioGroupReadOnly />;

export default Example;
